export default defineConfig({
  site: 'https://simongreer.co.uk',
  output: 'static',
  session: false,
  prefetch: false,
  adapter: cloudflare({
    imageService: { build: 'compile', runtime: 'cloudflare-binding' },
  }),
  integrations: [
    astroExpressiveCode({ themes: ['github-dark', 'github-light'] }),
    mdx(),
    sitemap(),
    icon({
